+function lineToPolygon(
+  x1: number,
+  y1: number,
+  x2: number,
+  y2: number,
+  thickness: number
+): { x: number; y: number }[] {
+  if (x1 === x2) {
+    // Vertical line
+    return [
+      { x: x1 - thickness / 2, y: y1 },
+      { x: x1 + thickness / 2, y: y1 },
+      { x: x2 + thickness / 2, y: y2 },
+      { x: x2 - thickness / 2, y: y2 },
+    ];
+  }
+  // Horizontal line (ER dividers are always axis-aligned)
+  return [
+    { x: x1, y: y1 - thickness / 2 },
+    { x: x1, y: y1 + thickness / 2 },
+    { x: x2, y: y2 + thickness / 2 },
+    { x: x2, y: y2 - thickness / 2 },
